#!/usr/bin/env node
/*
 * Folds the web app (index.html + css/styles.css + js/*.js) into a single
 * self-contained HTML string and writes it out as a JS module.
 *
 * The native shell renders that string directly with `source={{ html }}`, so
 * there are no relative asset paths to resolve inside the WebView, and the
 * whole UI travels inside the JS bundle — which is what makes it updatable
 * over the air by expo-updates.
 *
 * Run via `npm run bundle:web`; also wired to postinstall and prestart so a
 * clean checkout and an EAS build both regenerate it.
 */
const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');
const OUT = path.join(ROOT, 'src', 'webBundle.generated.js');

const read = (rel) => fs.readFileSync(path.join(ROOT, rel), 'utf8');

/* A literal `</script>` inside inlined JS would close the host tag early. */
const escapeForScriptTag = (code) => code.replace(/<\/(script)/gi, '<\\/$1');

/* Replacement *functions*, never replacement strings: the inlined CSS and JS
   contain `$` sequences (`'$' + total`, `$&`, …) that String.replace would
   otherwise expand as match patterns and splice the document into itself. */
const insert = (haystack, needle, replacement) => haystack.replace(needle, () => replacement);

function inline() {
  let html = read('index.html');

  const styles = read('css/styles.css');
  const linkTag = '<link rel="stylesheet" href="css/styles.css">';
  if (!html.includes(linkTag)) throw new Error('stylesheet link tag not found in index.html');
  html = insert(html, linkTag, '<style>\n' + styles + '\n</style>');

  ['js/qr.js', 'js/app.js'].forEach((src) => {
    const tag = '<script src="' + src + '"></script>';
    if (!html.includes(tag)) throw new Error('script tag not found in index.html: ' + src);
    html = insert(html, tag, '<script>\n' + escapeForScriptTag(read(src)) + '\n</script>');
  });

  if (/<(?:link|script)[^>]+(?:href|src)="(?!data:)/.test(html)) {
    throw new Error('index.html still references an external file after inlining');
  }

  /* Every source must survive byte for byte. Cheap, but it is what catches
     silent mangling of the inlined payload. */
  [['css/styles.css', styles],
   ['js/qr.js', read('js/qr.js')],
   ['js/app.js', read('js/app.js')]].forEach(([name, source]) => {
    if (!html.includes(escapeForScriptTag(source))) {
      throw new Error('inlined content for ' + name + ' was altered during assembly');
    }
  });

  return html;
}

const html = inline();
const banner = '/* GENERATED by scripts/bundle-web.js — do not edit. */\n' +
  '/* Source: index.html, css/styles.css, js/qr.js, js/app.js */\n';

fs.mkdirSync(path.dirname(OUT), { recursive: true });
fs.writeFileSync(OUT, banner + 'export default ' + JSON.stringify(html) + ';\n');

const kb = (Buffer.byteLength(html) / 1024).toFixed(1);
console.log('bundle-web: wrote src/webBundle.generated.js (' + kb + ' kB of inlined HTML)');
